import {
  useCallback,
  useId,
  useRef,
  useState,
  type ClipboardEvent,
  type KeyboardEvent,
} from 'react';
import { Button, Input } from '@jinx-ui/react';

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  hint?: string;
  value?: string[];
  defaultValue?: string[];
  maxTags?: number;
  disabled?: boolean;
  onChange?: (tags: string[]) => void;
};

function normalize(raw: string): string {
  return raw.trim().replace(/\s+/g, ' ');
}

function splitInput(raw: string): string[] {
  return raw
    .split(',')
    .map(normalize)
    .filter((tag) => tag.length > 0);
}

export default function TagPicker({
  label = 'Теги',
  placeholder = 'Введите тег и нажмите Enter',
  hint,
  value,
  defaultValue = [],
  maxTags,
  disabled = false,
  onChange,
}: TagPickerProps) {
  const fieldId = useId();
  const hintId = `${fieldId}-hint`;
  const statusId = `${fieldId}-status`;
  const inputRef = useRef<HTMLInputElement>(null);

  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const [status, setStatus] = useState('');

  const tags = value ?? internalTags;
  const isFull = typeof maxTags === 'number' && tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      if (value === undefined) {
        setInternalTags(next);
      }
      onChange?.(next);
    },
    [onChange, value],
  );

  const addTags = useCallback(
    (candidates: string[]) => {
      if (disabled || candidates.length === 0) {
        return;
      }
      const next = [...tags];
      const added: string[] = [];
      let rejectedDuplicate = false;

      for (const candidate of candidates) {
        if (typeof maxTags === 'number' && next.length >= maxTags) {
          setStatus(`Достигнут предел: ${maxTags}`);
          break;
        }
        const exists = next.some(
          (tag) => tag.toLowerCase() === candidate.toLowerCase(),
        );
        if (exists) {
          rejectedDuplicate = true;
          continue;
        }
        next.push(candidate);
        added.push(candidate);
      }

      if (added.length > 0) {
        commit(next);
        setStatus(`Добавлено: ${added.join(', ')}`);
      } else if (rejectedDuplicate) {
        setStatus('Такой тег уже добавлен');
      }
    },
    [commit, disabled, maxTags, tags],
  );

  const removeTag = useCallback(
    (target: string) => {
      if (disabled) {
        return;
      }
      commit(tags.filter((tag) => tag !== target));
      setStatus(`Удалено: ${target}`);
    },
    [commit, disabled, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTags(splitInput(draft));
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const handlePaste = (event: ClipboardEvent<HTMLInputElement>) => {
    const pasted = event.clipboardData.getData('text');
    if (!pasted.includes(',')) {
      return;
    }
    event.preventDefault();
    addTags(splitInput(pasted));
    setDraft('');
  };

  const handleBlur = () => {
    if (draft.trim() === '') {
      return;
    }
    addTags(splitInput(draft));
    setDraft('');
  };

  return (
    <div
      className="jx-field jx-stack"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-2)',
      }}
    >
      <label className="jx-label" htmlFor={fieldId}>
        {label}
      </label>

      <Input
        id={fieldId}
        ref={inputRef}
        type="text"
        value={draft}
        placeholder={isFull ? 'Лимит тегов исчерпан' : placeholder}
        disabled={disabled || isFull}
        aria-describedby={hint ? `${hintId} ${statusId}` : statusId}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        onBlur={handleBlur}
      />

      {hint ? (
        <p
          className="jx-hint"
          id={hintId}
          style={{ color: 'var(--jx-text-muted)', margin: 0 }}
        >
          {hint}
        </p>
      ) : null}

      {tags.length > 0 ? (
        <ul
          className="jx-cluster"
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2)',
            listStyle: 'none',
            margin: 0,
            padding: 0,
          }}
        >
          {tags.map((tag) => (
            <li
              key={tag.toLowerCase()}
              className="jx-tag"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1)',
                padding: 'var(--jx-space-1) var(--jx-space-2)',
                border: 'var(--jx-border-width) solid var(--jx-border)',
                borderRadius: 'var(--jx-radius)',
                background: 'var(--jx-surface-2)',
                color: 'var(--jx-text)',
              }}
            >
              <span>{tag}</span>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                disabled={disabled}
                aria-label={`Удалить тег ${tag}`}
                onClick={() => {
                  removeTag(tag);
                  inputRef.current?.focus();
                }}
              >
                ×
              </Button>
            </li>
          ))}
        </ul>
      ) : null}

      <p
        className="jx-hint"
        id={statusId}
        role="status"
        aria-live="polite"
        style={{ color: 'var(--jx-text-muted)', margin: 0 }}
      >
        {status}
      </p>
    </div>
  );
}

